const {DatabaseSync}=require('node:sqlite');
const db=new DatabaseSync('.codegraph/codegraph.db');
// fan-in = number of 'calls' edges targeting a node under internal/, node is function/method
const rows=db.prepare(\`
  select n.id, n.name, n.qualified_name, n.file_path, n.start_line, n.kind, count(*) c
  from edges e join nodes n on e.target=n.id
  where e.kind='calls' and n.file_path like 'internal/%' and n.kind in ('function','method')
  group by n.id order by c desc limit 15
\`).all();
for(const r of rows) console.log(r.c, '|', r.name, '|', r.file_path+':'+r.start_line, '|', r.kind);
" 2>/dev/null

